import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
#if canImport(Security)
import Security
import CryptoKit

/// Explicit Microsoft trust anchor for the Windows event collector only.
/// Published at https://www.microsoft.com/pkiops/docs/repository.htm (Root CA 2011).
/// SHA1 8f43288ad272f3103b6fb1428485ea3014c0bcfe; SHA256 checked below.
public final class CollectorTrust: NSObject, URLSessionTaskDelegate {
    static let rootDER = Data(base64Encoded:"")!
    public static let host = "v20.events.data.microsoft.com"
    public static func validate(_ trust: SecTrust, host: String) -> Bool {
        guard host == Self.host,
              SHA256.hash(data:rootDER).map({ String(format:"%02x",$0) }).joined() == "847df6a78497943f27fc72eb93f9a637320a02b561d0a91b09e87a7807ed7c61",
              let root = SecCertificateCreateWithData(nil,rootDER as CFData) else { return false }
        guard SecTrustSetPolicies(trust,SecPolicyCreateSSL(true,host as CFString)) == errSecSuccess,
              SecTrustSetAnchorCertificates(trust,[root] as CFArray) == errSecSuccess,
              SecTrustSetAnchorCertificatesOnly(trust,true) == errSecSuccess else { return false }
        return SecTrustEvaluateWithError(trust,nil)
    }
    public func urlSession(_ session: URLSession, didReceive challenge: URLAuthenticationChallenge, completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        guard challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              challenge.protectionSpace.host == Self.host,
              challenge.protectionSpace.protocol == "https", challenge.protectionSpace.port == 443,
              let trust = challenge.protectionSpace.serverTrust else { completionHandler(.performDefaultHandling,nil); return }
        if Self.validate(trust,host:challenge.protectionSpace.host) { completionHandler(.useCredential,URLCredential(trust:trust)) }
        else { completionHandler(.cancelAuthenticationChallenge,nil) }
    }
    public func urlSession(_ session: URLSession, task: URLSessionTask, willPerformHTTPRedirection response: HTTPURLResponse, newRequest request: URLRequest, completionHandler: @escaping (URLRequest?) -> Void) {
        // No plaintext redirects, including unauthenticated connectivity probes.
        guard request.url?.scheme == "https" else { completionHandler(nil); return }
        // Event credentials must never follow a redirect, even to another Microsoft host.
        if task.originalRequest?.value(forHTTPHeaderField:"tickets") != nil { completionHandler(nil) }
        else { completionHandler(request) }
    }
}
public enum XboxSessions {
    public static let shared = URLSession(configuration:.default,delegate:CollectorTrust(),delegateQueue:nil)
}
#else
public enum XboxSessions { public static let shared = URLSession.shared }
#endif

